def tool_call(req_id, name, arguments):
    return {'jsonrpc': '2.0', 'id': req_id, 'method': 'tools/call',
            'params': {'name': name, 'arguments': arguments}}

def handle(request, tools):
    rid = request.get('id')
    if request.get('method') != 'tools/call':
        return {'jsonrpc': '2.0', 'id': rid, 'error': {'code': -32601, 'message': 'Method not found'}}
    def res(content, err):
        return {'jsonrpc': '2.0', 'id': rid, 'result': {'content': content, 'isError': err}}
    params = request.get('params', {})
    name, args = params.get('name'), params.get('arguments', {})
    if name not in tools:
        return res('unknown tool', True)
    fn, schema = tools[name]
    if set(args) != set(schema):
        return res('invalid arguments', True)
    for k, t in schema.items():
        if type(args[k]) is not t:
            return res('invalid arguments', True)
    try:
        return res(fn(**args), False)
    except Exception:
        return res('tool failed', True)

