t = {'double': (lambda n: n * 2, {'n': int})}
r = handle({'jsonrpc': '2.0', 'id': 1, 'method': 'tools/call', 'params': {'name': 'double', 'arguments': {'n': 4}}}, t)
assert r == {'jsonrpc': '2.0', 'id': 1, 'result': {'content': 8, 'isError': False}}, r

