MARKERS = ['ignore previous', '.env', 'id_rsa', 'do not tell', '<important>']

def suspicious_tools(old, new):
    flagged = set()
    for name, desc in new.items():
        if name not in old or old[name] != desc:
            flagged.add(name)
        low = desc.lower()
        if any(m in low for m in MARKERS):
            flagged.add(name)
    return sorted(flagged)

